# -*- coding: utf-8 -*-
# Deconnexion mobile, logo mobile agrandi/centre, photo de profil,
# questions sport + niveau a l'inscription
# A lancer depuis la racine du dossier pompiers-app : python3 apply_update_9.py
import pathlib

FILES = {}

FILES['backend/prisma/schema.prisma'] = '// Schema Prisma - Application de suivi de camps d\'entrainement\n// Par defaut : SQLite (aucune installation requise).\n// Pour passer sur PostgreSQL en production, remplacer le provider ci-dessous\n// par "postgresql" et adapter DATABASE_URL dans .env\n\ngenerator client {\n  provider = "prisma-client-js"\n}\n\ndatasource db {\n  provider = "sqlite"\n  url      = env("DATABASE_URL")\n}\n\n// Note : pas d\'enum Prisma ici (ExerciseUnit / RecurrenceType) car SQLite ne supporte pas\n// les enums natifs. Les valeurs autorisees ("REPS"/"SECONDS", "DAILY"/"WEEKLY"/"EVERY_N_DAYS")\n// sont validees cote API avec zod.\n\nmodel User {\n  id             String   @id @default(cuid())\n  email          String   @unique\n  passwordHash   String\n  name           String\n  weightKg       Float?\n  heightCm       Float?\n  birthDate      DateTime?\n  sex            String?  // "F" | "M" | "AUTRE" | null, libre / optionnel\n  sport          String?  // pratique principale, libre choix dans une liste cote frontend\n  sportLevel     String?  // "LOISIR" | "COMPETITION" | null\n  avatarBase64   String?  // photo de profil encodee en data URL (redimensionnee cote client)\n  createdAt      DateTime @default(now())\n\n  memberships    CampMembership[]\n  createdCamps   Camp[]            @relation("CampCreator")\n  createdExos    Exercise[]        @relation("ExerciseCreator")\n  logs           ExerciseLog[]\n  subscriptions  PushSubscription[]\n  badges         UserBadge[]\n  campMessages   CampMessage[]\n  sentMessages   DirectMessage[]   @relation("MessageSender")\n  receivedMessages DirectMessage[] @relation("MessageRecipient")\n  chronoSessions ChronoSession[]\n  circuitLogs    CampCircuitLog[]\n  restDays       RestDay[]\n  favoriteCircuits FavoriteCircuit[]\n  reactions      Reaction[]\n  resetTokens    PasswordResetToken[]\n}\n\nmodel Exercise {\n  id          String       @id @default(cuid())\n  name        String\n  description String?\n  unit        String       // "REPS" ou "SECONDS"\n  isCustom    Boolean      @default(false)\n  createdById String?\n  createdBy   User?        @relation("ExerciseCreator", fields: [createdById], references: [id])\n  createdAt   DateTime     @default(now())\n\n  campExercises CampExercise[]\n  logs          ExerciseLog[]\n}\n\nmodel Camp {\n  id          String    @id @default(cuid())\n  name        String\n  description String?\n  code        String    @unique\n  createdById String\n  createdBy   User      @relation("CampCreator", fields: [createdById], references: [id])\n  startDate   DateTime?\n  endDate     DateTime?\n  createdAt   DateTime  @default(now())\n\n  exercises CampExercise[]\n  circuits  CampCircuit[]\n  members   CampMembership[]\n  logs      ExerciseLog[]\n  circuitLogs CampCircuitLog[]\n  messages  CampMessage[]\n}\n\n// Consigne d\'un exercice au sein d\'un camp : definie UNIQUEMENT par le createur du camp\n// (la "casquette entraineur"). Tous les membres suivent la meme consigne.\nmodel CampExercise {\n  id             String   @id @default(cuid())\n  campId         String\n  exerciseId     String\n  description    String?  // court descriptif/consigne redige par le createur du camp\n  targetSets     Int      @default(3)\n  targetMode     String   @default("FIXED") // "FIXED" (objectif chiffre) ou "MAX" (a fond, sans cible fixe)\n  targetValue    Int?     // nombre de repetitions OU de secondes vise (voir Exercise.unit) ; inutilise si targetMode = MAX\n  recurrenceType String   @default("DAILY") // "DAILY" | "WEEKLY" | "EVERY_N_DAYS"\n  daysOfWeek     String?  // JSON array ex: "[1,3,5]" (0=dimanche ... 6=samedi), utilise si WEEKLY\n  intervalDays   Int?     // utilise si EVERY_N_DAYS\n  startDate      DateTime @default(now())\n\n  camp     Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n  exercise Exercise @relation(fields: [exerciseId], references: [id])\n  logs     ExerciseLog[]\n\n  @@unique([campId, exerciseId])\n}\n\nmodel CampMembership {\n  id       String   @id @default(cuid())\n  userId   String\n  campId   String\n  joinedAt DateTime @default(now())\n  user     User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  camp     Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, campId])\n}\n\nmodel ExerciseLog {\n  id         String   @id @default(cuid())\n  userId     String\n  campId     String\n  exerciseId String\n  date       DateTime // jour concerne (heure normalisee a minuit)\n  setsDone   Int\n  valueDone  Int      // repetitions ou secondes realisees (moyenne/estimation par serie, cf notes)\n  completed  Boolean  @default(true)\n  createdAt  DateTime @default(now())\n\n  user         User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  camp         Camp          @relation(fields: [campId], references: [id], onDelete: Cascade)\n  exercise     Exercise      @relation(fields: [exerciseId], references: [id])\n  campExercise CampExercise? @relation(fields: [campId, exerciseId], references: [campId, exerciseId])\n\n  @@unique([userId, campId, exerciseId, date])\n}\n\nmodel PushSubscription {\n  id        String   @id @default(cuid())\n  userId    String\n  endpoint  String   @unique\n  p256dh    String\n  auth      String\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel UserBadge {\n  id        String   @id @default(cuid())\n  userId    String\n  badgeKey  String   // identifiant du badge, voir src/utils/badges.ts pour le catalogue\n  earnedAt  DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, badgeKey])\n}\n\n// Discussion de groupe entre les membres d\'un camp\nmodel CampMessage {\n  id        String   @id @default(cuid())\n  campId    String\n  userId    String\n  body      String\n  createdAt DateTime @default(now())\n\n  camp Camp @relation(fields: [campId], references: [id], onDelete: Cascade)\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Message prive entre deux utilisateurs (reserve aux personnes qui partagent au moins un camp)\nmodel DirectMessage {\n  id          String   @id @default(cuid())\n  senderId    String\n  recipientId String\n  body        String\n  createdAt   DateTime @default(now())\n\n  sender    User @relation("MessageSender", fields: [senderId], references: [id], onDelete: Cascade)\n  recipient User @relation("MessageRecipient", fields: [recipientId], references: [id], onDelete: Cascade)\n}\n\n// Seance de circuit training "libre" (construite depuis l\'onglet Chrono, pas liee a un camp).\n// Enregistree une fois terminee, pour alimenter l\'historique d\'activite de l\'utilisateur.\nmodel ChronoSession {\n  id                   String   @id @default(cuid())\n  userId               String\n  name                 String? // nom optionnel donne par l\'utilisateur\n  items                String  // JSON : liste ordonnee des noms d\'exercices du circuit\n  workSeconds          Int\n  restSeconds          Int\n  rounds               Int\n  roundRestSeconds     Int\n  totalDurationSeconds Int\n  completedAt          DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Circuit training defini par le createur d\'un camp (alternative aux exercices individuels).\n// Compose d\'une liste ordonnee d\'exercices avec temps de travail/repos, nombre de tours, etc.\nmodel CampCircuit {\n  id               String   @id @default(cuid())\n  campId           String\n  name             String\n  description      String?\n  items            String   // JSON : [{ "exerciseId": "...", "name": "..." }, ...] ordonne\n  workSeconds      Int\n  restSeconds      Int\n  rounds           Int\n  roundRestSeconds Int\n  recurrenceType   String   @default("DAILY")\n  daysOfWeek       String?\n  intervalDays     Int?\n  startDate        DateTime @default(now())\n\n  camp Camp             @relation(fields: [campId], references: [id], onDelete: Cascade)\n  logs CampCircuitLog[]\n}\n\n// Validation, par un membre, d\'un circuit de camp realise un jour donne\nmodel CampCircuitLog {\n  id              String   @id @default(cuid())\n  userId          String\n  campCircuitId   String\n  campId          String\n  date            DateTime\n  durationSeconds Int\n  completed       Boolean  @default(true)\n  createdAt       DateTime @default(now())\n\n  user        User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  campCircuit CampCircuit @relation(fields: [campCircuitId], references: [id], onDelete: Cascade)\n  camp        Camp        @relation(fields: [campId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, campCircuitId, date])\n}\n\n// Jour marque comme "repos justifie" par l\'utilisateur (blessure, voyage...) : ce jour\n// n\'est jamais compte comme un manque dans les calculs de regularite/streak, ni comme du\n// depend  (il est neutre). S\'applique globalement, tous camps/exercices confondus.\nmodel RestDay {\n  id        String   @id @default(cuid())\n  userId    String\n  date      DateTime // jour concerne (heure normalisee a minuit)\n  reason    String?\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, date])\n}\n\n// Circuit training "favori" enregistre par un utilisateur depuis l\'onglet Chrono,\n// pour le relancer directement sans le reconstruire.\nmodel FavoriteCircuit {\n  id               String   @id @default(cuid())\n  userId           String\n  name             String\n  items            String   // JSON : liste ordonnee des noms d\'exercices\n  workSeconds      Int\n  restSeconds      Int\n  rounds           Int\n  roundRestSeconds Int\n  createdAt        DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Reaction rapide (encouragement) laissee par un membre de camp sur une seance validee\n// par un autre membre (exercice ou circuit). Purement social, aucun impact sur les stats.\nmodel Reaction {\n  id         String   @id @default(cuid())\n  userId     String   // qui reagit\n  targetType String   // "exercise" ou "circuit" (type de log cible)\n  targetId   String   // id du ExerciseLog ou CampCircuitLog cible\n  type       String   // cle du type de reaction, voir src/utils/reactions.ts\n  createdAt  DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, targetType, targetId, type])\n}\n\n// Jeton de reinitialisation de mot de passe, a duree de vie limitee\nmodel PasswordResetToken {\n  id        String   @id @default(cuid())\n  userId    String\n  token     String   @unique\n  expiresAt DateTime\n  used      Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n'
FILES['backend/src/routes/auth.ts'] = 'import { Router } from "express";\nimport bcrypt from "bcryptjs";\nimport jwt from "jsonwebtoken";\nimport crypto from "crypto";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { sendEmail } from "../services/email";\n\nconst router = Router();\n\nconst registerSchema = z.object({\n  email: z.string().email("Adresse email invalide."),\n  password: z.string().min(8, "Le mot de passe doit faire au moins 8 caracteres."),\n  name: z.string().min(1, "Le nom est requis."),\n  sport: z.string().max(100).optional().nullable(),\n  sportLevel: z.enum(["LOISIR", "COMPETITION"]).optional().nullable(),\n});\n\nconst loginSchema = z.object({\n  email: z.string().email(),\n  password: z.string().min(1),\n});\n\nfunction signToken(userId: string): string {\n  const secret = process.env.JWT_SECRET as string;\n  const expiresIn = process.env.JWT_EXPIRES_IN || "30d";\n  return jwt.sign({ userId }, secret, { expiresIn } as jwt.SignOptions);\n}\n\nfunction toPublicUser(user: {\n  id: string;\n  email: string;\n  name: string;\n  weightKg: number | null;\n  heightCm: number | null;\n  birthDate: Date | null;\n  sex: string | null;\n  sport: string | null;\n  sportLevel: string | null;\n  avatarBase64: string | null;\n}) {\n  return {\n    id: user.id,\n    email: user.email,\n    name: user.name,\n    weightKg: user.weightKg,\n    heightCm: user.heightCm,\n    birthDate: user.birthDate,\n    sex: user.sex,\n    sport: user.sport,\n    sportLevel: user.sportLevel,\n    avatarBase64: user.avatarBase64,\n  };\n}\n\nrouter.post("/register", async (req, res) => {\n  const parsed = registerSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const { email, password, name, sport, sportLevel } = parsed.data;\n\n  const existing = await prisma.user.findUnique({ where: { email } });\n  if (existing) {\n    return res.status(409).json({ error: "Un compte existe deja avec cet email." });\n  }\n\n  const passwordHash = await bcrypt.hash(password, 10);\n  const user = await prisma.user.create({\n    data: { email, passwordHash, name, sport: sport || null, sportLevel: sportLevel || null },\n  });\n\n  const token = signToken(user.id);\n  return res.status(201).json({ token, user: toPublicUser(user) });\n});\n\nrouter.post("/login", async (req, res) => {\n  const parsed = loginSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Email et mot de passe requis." });\n  }\n  const { email, password } = parsed.data;\n\n  const user = await prisma.user.findUnique({ where: { email } });\n  if (!user) {\n    return res.status(401).json({ error: "Email ou mot de passe incorrect." });\n  }\n\n  const valid = await bcrypt.compare(password, user.passwordHash);\n  if (!valid) {\n    return res.status(401).json({ error: "Email ou mot de passe incorrect." });\n  }\n\n  const token = signToken(user.id);\n  return res.json({ token, user: toPublicUser(user) });\n});\n\nconst forgotSchema = z.object({ email: z.string().email() });\n\n// Demande de reinitialisation : genere un jeton valable 1h et envoie un email (si configure).\n// Repond toujours de la meme facon, que l\'email existe ou non, pour ne pas reveler qui a un compte.\nrouter.post("/forgot-password", async (req, res) => {\n  const parsed = forgotSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Adresse email invalide." });\n  }\n  const { email } = parsed.data;\n\n  const genericResponse = {\n    message: "Si un compte existe avec cet email, un lien de reinitialisation vient d\'etre envoye.",\n  };\n\n  const user = await prisma.user.findUnique({ where: { email } });\n  if (!user) return res.json(genericResponse);\n\n  const token = crypto.randomBytes(32).toString("hex");\n  const expiresAt = new Date(Date.now() + 60 * 60 * 1000); // 1 heure\n\n  await prisma.passwordResetToken.create({ data: { userId: user.id, token, expiresAt } });\n\n  const frontendUrl = process.env.FRONTEND_URL || "http://localhost:5173";\n  const resetLink = `${frontendUrl}/reinitialiser-mot-de-passe?token=${token}`;\n\n  await sendEmail(\n    email,\n    "Reinitialisation de ton mot de passe GoTeam",\n    `Bonjour ${user.name},\\n\\nClique sur ce lien pour choisir un nouveau mot de passe (valable 1 heure) :\\n${resetLink}\\n\\nSi tu n\'es pas a l\'origine de cette demande, ignore simplement cet email.`\n  );\n\n  return res.json(genericResponse);\n});\n\nconst resetSchema = z.object({\n  token: z.string().min(1),\n  newPassword: z.string().min(8, "Le mot de passe doit faire au moins 8 caracteres."),\n});\n\n// Applique le nouveau mot de passe si le jeton est valide, non expire et non deja utilise\nrouter.post("/reset-password", async (req, res) => {\n  const parsed = resetSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const { token, newPassword } = parsed.data;\n\n  const resetToken = await prisma.passwordResetToken.findUnique({ where: { token } });\n  if (!resetToken || resetToken.used || resetToken.expiresAt.getTime() < Date.now()) {\n    return res.status(400).json({ error: "Ce lien de reinitialisation est invalide ou a expire." });\n  }\n\n  const passwordHash = await bcrypt.hash(newPassword, 10);\n  await prisma.$transaction([\n    prisma.user.update({ where: { id: resetToken.userId }, data: { passwordHash } }),\n    prisma.passwordResetToken.update({ where: { id: resetToken.id }, data: { used: true } }),\n  ]);\n\n  res.json({ message: "Mot de passe mis a jour, tu peux te connecter." });\n});\n\nexport default router;\n'
FILES['backend/src/routes/users.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nconst updateSchema = z.object({\n  name: z.string().min(1).optional(),\n  weightKg: z.number().positive().nullable().optional(),\n  heightCm: z.number().positive().nullable().optional(),\n  birthDate: z.string().nullable().optional(), // format ISO "YYYY-MM-DD"\n  sex: z.enum(["F", "M", "AUTRE"]).nullable().optional(),\n  sport: z.string().max(100).nullable().optional(),\n  sportLevel: z.enum(["LOISIR", "COMPETITION"]).nullable().optional(),\n  // data URL (ex: "data:image/jpeg;base64,...") ; limite large mais raisonnable une fois\n  // l\'image redimensionnee/compressee cote client avant l\'envoi.\n  avatarBase64: z.string().max(2_000_000).nullable().optional(),\n});\n\nrouter.get("/me", async (req: AuthRequest, res) => {\n  const user = await prisma.user.findUnique({ where: { id: req.userId } });\n  if (!user) return res.status(404).json({ error: "Utilisateur introuvable." });\n  const { passwordHash, ...publicUser } = user;\n  res.json(publicUser);\n});\n\nrouter.put("/me", async (req: AuthRequest, res) => {\n  const parsed = updateSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const { birthDate, ...rest } = parsed.data;\n\n  const user = await prisma.user.update({\n    where: { id: req.userId },\n    data: {\n      ...rest,\n      ...(birthDate !== undefined ? { birthDate: birthDate ? new Date(birthDate) : null } : {}),\n    },\n  });\n  const { passwordHash, ...publicUser } = user;\n  res.json(publicUser);\n});\n\nexport default router;\n'
FILES['frontend/src/context/AuthContext.tsx'] = 'import { createContext, useContext, useEffect, useState, ReactNode } from "react";\nimport { api } from "../api/client";\n\nexport interface UserProfile {\n  id: string;\n  email: string;\n  name: string;\n  weightKg: number | null;\n  heightCm: number | null;\n  birthDate: string | null;\n  sex: string | null;\n  sport: string | null;\n  sportLevel: string | null;\n  avatarBase64: string | null;\n}\n\ninterface AuthContextValue {\n  user: UserProfile | null;\n  loading: boolean;\n  login: (email: string, password: string) => Promise<void>;\n  register: (\n    email: string,\n    password: string,\n    name: string,\n    sport?: string | null,\n    sportLevel?: string | null\n  ) => Promise<void>;\n  logout: () => void;\n  refreshUser: () => Promise<void>;\n}\n\nconst AuthContext = createContext<AuthContextValue | undefined>(undefined);\n\nexport function AuthProvider({ children }: { children: ReactNode }) {\n  const [user, setUser] = useState<UserProfile | null>(null);\n  const [loading, setLoading] = useState(true);\n\n  async function refreshUser() {\n    try {\n      const me = await api.get<UserProfile>("/users/me");\n      setUser(me);\n    } catch {\n      setUser(null);\n      localStorage.removeItem("token");\n    }\n  }\n\n  useEffect(() => {\n    const token = localStorage.getItem("token");\n    if (!token) {\n      setLoading(false);\n      return;\n    }\n    refreshUser().finally(() => setLoading(false));\n  }, []);\n\n  async function login(email: string, password: string) {\n    const res = await api.post<{ token: string; user: UserProfile }>("/auth/login", { email, password });\n    localStorage.setItem("token", res.token);\n    setUser(res.user);\n  }\n\n  async function register(\n    email: string,\n    password: string,\n    name: string,\n    sport?: string | null,\n    sportLevel?: string | null\n  ) {\n    const res = await api.post<{ token: string; user: UserProfile }>("/auth/register", {\n      email,\n      password,\n      name,\n      sport: sport || null,\n      sportLevel: sportLevel || null,\n    });\n    localStorage.setItem("token", res.token);\n    setUser(res.user);\n  }\n\n  function logout() {\n    localStorage.removeItem("token");\n    setUser(null);\n  }\n\n  return (\n    <AuthContext.Provider value={{ user, loading, login, register, logout, refreshUser }}>\n      {children}\n    </AuthContext.Provider>\n  );\n}\n\nexport function useAuth() {\n  const ctx = useContext(AuthContext);\n  if (!ctx) throw new Error("useAuth doit etre utilise dans un AuthProvider");\n  return ctx;\n}\n'
FILES['frontend/src/lib/sports.ts'] = '// Liste large : sports collectifs, individuels, et activites de forme/bien-etre.\nexport const SPORTS_LIST = [\n  "Football",\n  "Rugby",\n  "Basketball",\n  "Handball",\n  "Volleyball",\n  "Tennis",\n  "Badminton",\n  "Natation",\n  "Athletisme",\n  "Course a pied",\n  "Cyclisme / Velo",\n  "Musculation",\n  "Escalade",\n  "Marche / Randonnee",\n  "Gymnastique d\'entretien",\n  "Arts martiaux / Sports de combat",\n  "Danse",\n  "Ski / Sports d\'hiver",\n  "Crossfit",\n  "Yoga / Pilates",\n  "Preparation physique (pompiers, armee, police...)",\n  "Autre",\n];\n\nexport const SPORT_LEVELS: { value: "LOISIR" | "COMPETITION"; label: string }[] = [\n  { value: "LOISIR", label: "Loisir / bien-etre, pour le plaisir" },\n  { value: "COMPETITION", label: "Competition" },\n];\n'
FILES['frontend/src/lib/image.ts'] = '// Redimensionne et compresse une image cote client (via canvas) avant de l\'envoyer au serveur,\n// pour eviter de stocker des photos trop lourdes en base de donnees.\nexport function resizeImageFile(file: File, maxSize = 320, quality = 0.8): Promise<string> {\n  return new Promise((resolve, reject) => {\n    const reader = new FileReader();\n    reader.onerror = () => reject(new Error("Lecture du fichier impossible."));\n    reader.onload = () => {\n      const img = new Image();\n      img.onerror = () => reject(new Error("Image invalide."));\n      img.onload = () => {\n        let { width, height } = img;\n        if (width > height && width > maxSize) {\n          height = Math.round((height * maxSize) / width);\n          width = maxSize;\n        } else if (height > maxSize) {\n          width = Math.round((width * maxSize) / height);\n          height = maxSize;\n        }\n\n        const canvas = document.createElement("canvas");\n        canvas.width = width;\n        canvas.height = height;\n        const ctx = canvas.getContext("2d");\n        if (!ctx) {\n          reject(new Error("Canvas non supporte."));\n          return;\n        }\n        ctx.drawImage(img, 0, 0, width, height);\n        resolve(canvas.toDataURL("image/jpeg", quality));\n      };\n      img.src = reader.result as string;\n    };\n    reader.readAsDataURL(file);\n  });\n}\n'
FILES['frontend/src/pages/Register.tsx'] = 'import { FormEvent, useState } from "react";\nimport { Link, Navigate, useNavigate } from "react-router-dom";\nimport { useAuth } from "../context/AuthContext";\nimport { ApiError } from "../api/client";\nimport { SPORTS_LIST, SPORT_LEVELS } from "../lib/sports";\n\nexport default function Register() {\n  const { register, user } = useAuth();\n  const navigate = useNavigate();\n  const [name, setName] = useState("");\n  const [email, setEmail] = useState("");\n  const [password, setPassword] = useState("");\n  const [sport, setSport] = useState("");\n  const [sportLevel, setSportLevel] = useState<"LOISIR" | "COMPETITION" | "">("");\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n\n  if (user) return <Navigate to="/aujourdhui" replace />;\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    setError(null);\n    setBusy(true);\n    try {\n      await register(email, password, name, sport || null, sportLevel || null);\n      navigate("/profil");\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Inscription impossible, reessaie.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <div className="min-h-screen flex items-center justify-center px-5">\n      <div className="w-full max-w-sm">\n        <div className="flex justify-center mb-8">\n          <img src="/logo-full.png" alt="GoTeam" className="h-24 w-auto" />\n        </div>\n\n        <div className="bg-surface border border-border rounded-xl p-6">\n          <h1 className="font-display text-2xl uppercase tracking-wide mb-1">Creer un compte</h1>\n          <p className="text-muted text-sm mb-6">Rejoins ou cree ton premier camp d\'entrainement.</p>\n\n          <form onSubmit={onSubmit} className="space-y-4">\n            <div>\n              <label className="block text-sm text-muted mb-1" htmlFor="name">\n                Prenom\n              </label>\n              <input\n                id="name"\n                required\n                value={name}\n                onChange={(e) => setName(e.target.value)}\n                className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n              />\n            </div>\n            <div>\n              <label className="block text-sm text-muted mb-1" htmlFor="email">\n                Email\n              </label>\n              <input\n                id="email"\n                type="email"\n                required\n                value={email}\n                onChange={(e) => setEmail(e.target.value)}\n                className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n              />\n            </div>\n            <div>\n              <label className="block text-sm text-muted mb-1" htmlFor="password">\n                Mot de passe\n              </label>\n              <input\n                id="password"\n                type="password"\n                required\n                minLength={8}\n                value={password}\n                onChange={(e) => setPassword(e.target.value)}\n                className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n              />\n              <p className="text-xs text-muted mt-1">8 caracteres minimum.</p>\n            </div>\n\n            <div>\n              <label className="block text-sm text-muted mb-1" htmlFor="sport">\n                Ton sport / activite principale (optionnel)\n              </label>\n              <select\n                id="sport"\n                value={sport}\n                onChange={(e) => setSport(e.target.value)}\n                className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n              >\n                <option value="">Je ne pratique rien en particulier / je decouvre</option>\n                {SPORTS_LIST.map((s) => (\n                  <option key={s} value={s}>\n                    {s}\n                  </option>\n                ))}\n              </select>\n            </div>\n\n            {sport && (\n              <div>\n                <label className="block text-sm text-muted mb-1">Niveau de pratique</label>\n                <div className="flex gap-2">\n                  {SPORT_LEVELS.map((lvl) => (\n                    <button\n                      type="button"\n                      key={lvl.value}\n                      onClick={() => setSportLevel(lvl.value)}\n                      className={`flex-1 text-xs px-3 py-2 rounded-md border ${\n                        sportLevel === lvl.value\n                          ? "bg-accent/20 border-accent text-text"\n                          : "bg-surface2 border-border text-muted"\n                      }`}\n                    >\n                      {lvl.label}\n                    </button>\n                  ))}\n                </div>\n              </div>\n            )}\n\n            {error && <p className="text-sm text-accent">{error}</p>}\n\n            <button\n              type="submit"\n              disabled={busy}\n              className="w-full bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md py-2 disabled:opacity-60"\n            >\n              {busy ? "Creation..." : "Creer mon compte"}\n            </button>\n          </form>\n        </div>\n\n        <p className="text-center text-sm text-muted mt-4">\n          Deja un compte ?{" "}\n          <Link to="/connexion" className="text-accent hover:text-accentSoft">\n            Connecte-toi\n          </Link>\n        </p>\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Profile.tsx'] = 'import { FormEvent, useEffect, useRef, useState } from "react";\nimport { Link, useNavigate } from "react-router-dom";\nimport { useAuth } from "../context/AuthContext";\nimport { api, ApiError } from "../api/client";\nimport { enablePushNotifications } from "../lib/push";\nimport { resizeImageFile } from "../lib/image";\nimport { SPORTS_LIST, SPORT_LEVELS } from "../lib/sports";\n\ninterface Badge {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n  earned: boolean;\n  earnedAt: string | null;\n}\n\nexport default function Profile() {\n  const { user, refreshUser, logout } = useAuth();\n  const navigate = useNavigate();\n  const [weightKg, setWeightKg] = useState(user?.weightKg?.toString() ?? "");\n  const [heightCm, setHeightCm] = useState(user?.heightCm?.toString() ?? "");\n  const [birthDate, setBirthDate] = useState(user?.birthDate?.slice(0, 10) ?? "");\n  const [sex, setSex] = useState(user?.sex ?? "");\n  const [sport, setSport] = useState(user?.sport ?? "");\n  const [sportLevel, setSportLevel] = useState(user?.sportLevel ?? "");\n  const [message, setMessage] = useState<string | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n  const [badges, setBadges] = useState<Badge[] | null>(null);\n  const [avatarUploading, setAvatarUploading] = useState(false);\n  const fileInputRef = useRef<HTMLInputElement>(null);\n\n  useEffect(() => {\n    api.get<Badge[]>("/badges").then(setBadges);\n  }, []);\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    setError(null);\n    setMessage(null);\n    setBusy(true);\n    try {\n      await api.put("/users/me", {\n        weightKg: weightKg ? Number(weightKg) : null,\n        heightCm: heightCm ? Number(heightCm) : null,\n        birthDate: birthDate || null,\n        sex: sex || null,\n        sport: sport || null,\n        sportLevel: sportLevel || null,\n      });\n      await refreshUser();\n      setMessage("Profil mis a jour.");\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Impossible de mettre a jour le profil.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  async function onAvatarChange(e: React.ChangeEvent<HTMLInputElement>) {\n    const file = e.target.files?.[0];\n    if (!file) return;\n    setAvatarUploading(true);\n    setError(null);\n    try {\n      const dataUrl = await resizeImageFile(file);\n      await api.put("/users/me", { avatarBase64: dataUrl });\n      await refreshUser();\n    } catch {\n      setError("Impossible de mettre a jour la photo de profil.");\n    } finally {\n      setAvatarUploading(false);\n      if (fileInputRef.current) fileInputRef.current.value = "";\n    }\n  }\n\n  async function removeAvatar() {\n    setAvatarUploading(true);\n    try {\n      await api.put("/users/me", { avatarBase64: null });\n      await refreshUser();\n    } finally {\n      setAvatarUploading(false);\n    }\n  }\n\n  async function onEnableNotifications() {\n    setMessage(null);\n    setError(null);\n    try {\n      const result = await enablePushNotifications();\n      setMessage(result);\n    } catch {\n      setError("Impossible d\'activer les notifications sur cet appareil.");\n    }\n  }\n\n  function onLogout() {\n    logout();\n    navigate("/connexion");\n  }\n\n  return (\n    <div className="max-w-lg">\n      <div className="flex items-start justify-between gap-3 mb-1">\n        <h1 className="font-display text-3xl uppercase tracking-wide">Mon profil</h1>\n        <button onClick={onLogout} className="text-sm text-muted hover:text-accent transition-colors shrink-0">\n          Se deconnecter\n        </button>\n      </div>\n      <p className="text-muted text-sm mb-6">Ces infos sont juste pour toi, pas partagees avec les autres membres.</p>\n\n      <div className="flex gap-2 mb-6 md:hidden">\n        <Link\n          to="/exercices"\n          className="flex-1 text-center bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-2 text-sm"\n        >\n          📚 Exercices\n        </Link>\n        <Link\n          to="/historique"\n          className="flex-1 text-center bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-2 text-sm"\n        >\n          📈 Historique\n        </Link>\n      </div>\n\n      <div className="bg-surface border border-border rounded-xl p-6 mb-6 flex items-center gap-4">\n        <div className="w-20 h-20 rounded-full bg-surface2 border border-border overflow-hidden flex items-center justify-center shrink-0">\n          {user?.avatarBase64 ? (\n            <img src={user.avatarBase64} alt="" className="w-full h-full object-cover" />\n          ) : (\n            <span className="text-2xl text-muted">{user?.name?.[0]?.toUpperCase() ?? "?"}</span>\n          )}\n        </div>\n        <div>\n          <input ref={fileInputRef} type="file" accept="image/*" onChange={onAvatarChange} className="hidden" id="avatarInput" />\n          <label\n            htmlFor="avatarInput"\n            className="inline-block cursor-pointer bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-1.5 text-sm"\n          >\n            {avatarUploading ? "..." : "Changer la photo"}\n          </label>\n          {user?.avatarBase64 && (\n            <button onClick={removeAvatar} disabled={avatarUploading} className="block text-xs text-muted hover:text-accent mt-1">\n              Retirer la photo\n            </button>\n          )}\n        </div>\n      </div>\n\n      <form onSubmit={onSubmit} className="bg-surface border border-border rounded-xl p-6 space-y-4">\n        <div className="grid grid-cols-2 gap-4">\n          <div>\n            <label className="block text-sm text-muted mb-1" htmlFor="weight">\n              Poids (kg)\n            </label>\n            <input\n              id="weight"\n              type="number"\n              step="0.1"\n              min="0"\n              value={weightKg}\n              onChange={(e) => setWeightKg(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n            />\n          </div>\n          <div>\n            <label className="block text-sm text-muted mb-1" htmlFor="height">\n              Taille (cm)\n            </label>\n            <input\n              id="height"\n              type="number"\n              step="0.1"\n              min="0"\n              value={heightCm}\n              onChange={(e) => setHeightCm(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n            />\n          </div>\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-1" htmlFor="birthDate">\n            Date de naissance\n          </label>\n          <input\n            id="birthDate"\n            type="date"\n            value={birthDate}\n            onChange={(e) => setBirthDate(e.target.value)}\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n          />\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-1" htmlFor="sex">\n            Sexe (optionnel)\n          </label>\n          <select\n            id="sex"\n            value={sex}\n            onChange={(e) => setSex(e.target.value)}\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n          >\n            <option value="">Ne souhaite pas preciser</option>\n            <option value="F">Femme</option>\n            <option value="M">Homme</option>\n            <option value="AUTRE">Autre</option>\n          </select>\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-1" htmlFor="sport">\n            Sport / activite principale\n          </label>\n          <select\n            id="sport"\n            value={sport}\n            onChange={(e) => setSport(e.target.value)}\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n          >\n            <option value="">Non precise</option>\n            {SPORTS_LIST.map((s) => (\n              <option key={s} value={s}>\n                {s}\n              </option>\n            ))}\n          </select>\n        </div>\n\n        {sport && (\n          <div>\n            <label className="block text-sm text-muted mb-1">Niveau de pratique</label>\n            <div className="flex gap-2">\n              {SPORT_LEVELS.map((lvl) => (\n                <button\n                  type="button"\n                  key={lvl.value}\n                  onClick={() => setSportLevel(lvl.value)}\n                  className={`flex-1 text-xs px-3 py-2 rounded-md border ${\n                    sportLevel === lvl.value ? "bg-accent/20 border-accent text-text" : "bg-surface2 border-border text-muted"\n                  }`}\n                >\n                  {lvl.label}\n                </button>\n              ))}\n            </div>\n          </div>\n        )}\n\n        {message && <p className="text-sm text-success">{message}</p>}\n        {error && <p className="text-sm text-accent">{error}</p>}\n\n        <button\n          type="submit"\n          disabled={busy}\n          className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-5 py-2 disabled:opacity-60"\n        >\n          {busy ? "Enregistrement..." : "Enregistrer"}\n        </button>\n      </form>\n\n      <div className="bg-surface border border-border rounded-xl p-6 mt-6">\n        <h2 className="font-display text-lg uppercase tracking-wide mb-1">Rappels</h2>\n        <p className="text-muted text-sm mb-4">\n          Active les notifications pour recevoir un rappel les jours ou une seance est prevue.\n        </p>\n        <button\n          onClick={onEnableNotifications}\n          className="bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-4 py-2 text-sm"\n        >\n          Activer les notifications\n        </button>\n      </div>\n      <div className="bg-surface border border-border rounded-xl p-6 mt-6">\n        <h2 className="font-display text-lg uppercase tracking-wide mb-1">Mes badges</h2>\n        <p className="text-muted text-sm mb-4">\n          Bases sur ta regularite personnelle uniquement, pas de comparaison avec les autres membres.\n        </p>\n        {badges === null && <p className="text-muted text-sm">Chargement...</p>}\n        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">\n          {badges?.map((b) => (\n            <div\n              key={b.key}\n              title={b.description}\n              className={`rounded-lg p-3 text-center border ${\n                b.earned ? "bg-accent/10 border-accent" : "bg-surface2 border-border opacity-40"\n              }`}\n            >\n              <p className="text-2xl mb-1">{b.emoji}</p>\n              <p className="text-xs font-medium">{b.name}</p>\n            </div>\n          ))}\n        </div>\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/components/Layout.tsx'] = 'import { NavLink, useNavigate } from "react-router-dom";\nimport { ReactNode } from "react";\nimport { useAuth } from "../context/AuthContext";\n\nconst desktopNavItems = [\n  { to: "/aujourdhui", label: "Aujourd\'hui" },\n  { to: "/camps", label: "Mes camps" },\n  { to: "/chrono", label: "Chrono" },\n  { to: "/exercices", label: "Exercices" },\n  { to: "/messages", label: "Messages" },\n  { to: "/historique", label: "Historique" },\n  { to: "/profil", label: "Profil" },\n];\n\n// Sur mobile, la barre du bas ne montre que l\'essentiel : le Chrono a sa propre bulle\n// centrale, les autres onglets (Exercices, Historique) restent accessibles depuis le menu\n// complet sur ordinateur, ou via des liens dans "Mes camps" / "Profil" sur mobile.\nconst mobileLeftItems = [\n  { to: "/aujourdhui", label: "Aujourd\'hui", icon: "📅" },\n  { to: "/camps", label: "Camps", icon: "🏕️" },\n];\nconst mobileRightItems = [\n  { to: "/messages", label: "Messages", icon: "💬" },\n  { to: "/profil", label: "Profil", icon: "👤" },\n];\n\nexport default function Layout({ children }: { children: ReactNode }) {\n  const { user, logout } = useAuth();\n  const navigate = useNavigate();\n\n  return (\n    <div className="min-h-screen flex flex-col md:flex-row">\n      <header className="md:w-64 md:min-h-screen border-b md:border-b-0 md:border-r border-border bg-surface flex md:flex-col justify-between">\n        <div className="p-4 md:p-6 w-full">\n          <div className="flex items-center justify-center md:justify-start gap-2 mb-0 md:mb-8">\n            <img src="/logo-mark.png" alt="" className="w-11 h-11 md:w-8 md:h-8 object-contain" />\n            <span className="font-display text-xl md:text-lg tracking-wide uppercase">GoTeam</span>\n          </div>\n          <nav className="hidden md:flex md:flex-col gap-1">\n            {desktopNavItems.map((item) => (\n              <NavLink\n                key={item.to}\n                to={item.to}\n                className={({ isActive }) =>\n                  `px-3 py-2 rounded-md text-sm font-medium transition-colors ${\n                    isActive ? "bg-accent/15 text-accent" : "text-muted hover:text-text hover:bg-surface2"\n                  }`\n                }\n              >\n                {item.label}\n              </NavLink>\n            ))}\n          </nav>\n        </div>\n        <div className="p-6 hidden md:block">\n          {user && <p className="text-xs text-muted mb-2 truncate">{user.name}</p>}\n          <button\n            onClick={() => {\n              logout();\n              navigate("/connexion");\n            }}\n            className="text-sm text-muted hover:text-accent transition-colors"\n          >\n            Se deconnecter\n          </button>\n        </div>\n      </header>\n\n      <main className="flex-1 p-5 pb-24 md:p-10 md:pb-10 max-w-4xl mx-auto w-full order-1">{children}</main>\n\n      {/* Barre de navigation mobile, fixee en bas, avec le Chrono en bulle centrale */}\n      <nav className="md:hidden fixed bottom-0 inset-x-0 bg-surface border-t border-border flex items-end justify-around pb-1 pt-2 z-40">\n        {mobileLeftItems.map((item) => (\n          <NavLink\n            key={item.to}\n            to={item.to}\n            className={({ isActive }) =>\n              `flex-1 flex flex-col items-center gap-0.5 py-1 text-[10px] font-medium ${\n                isActive ? "text-accent" : "text-muted"\n              }`\n            }\n          >\n            <span className="text-lg leading-none">{item.icon}</span>\n            {item.label}\n          </NavLink>\n        ))}\n\n        <NavLink to="/chrono" className="flex-1 flex flex-col items-center -mt-7">\n          {({ isActive }) => (\n            <>\n              <span\n                className={`w-14 h-14 rounded-full flex items-center justify-center text-2xl shadow-lg border-4 border-bg ${\n                  isActive ? "bg-accentSoft" : "bg-accent"\n                } text-bg`}\n              >\n                ⏱\n              </span>\n              <span className={`text-[10px] font-medium mt-0.5 ${isActive ? "text-accent" : "text-muted"}`}>\n                Chrono\n              </span>\n            </>\n          )}\n        </NavLink>\n\n        {mobileRightItems.map((item) => (\n          <NavLink\n            key={item.to}\n            to={item.to}\n            className={({ isActive }) =>\n              `flex-1 flex flex-col items-center gap-0.5 py-1 text-[10px] font-medium ${\n                isActive ? "text-accent" : "text-muted"\n              }`\n            }\n          >\n            <span className="text-lg leading-none">{item.icon}</span>\n            {item.label}\n          </NavLink>\n        ))}\n      </nav>\n    </div>\n  );\n}\n'

for rel_path, content in FILES.items():
    p = pathlib.Path(rel_path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content, encoding='utf-8')
    print('OK ->', rel_path)

